script:
frappe.ui.form.on('Orchestrator Settings', {
    test: function(frm) {
        frappe.call({
            method: "orchestrator.api.test_telegram",
            args: {
                telegram_bot_token: frm.doc.telegram_bot_token,
                chat_id: frm.doc.chat_id
            },
            callback: function(r) {
                if(r.message) {
                    frappe.msgprint(r.message);
                }
            }
        });
    }
});

frappe.ui.form.on('App Manager', {
    refresh(frm) {

        // === Total Sites Card (green) ===
        const total_sites = (frm.doc.sites || []).length;
        frm.set_df_property('total_sites', 'options', `
            <div style="
                background-color: #28a745;
                color: white;
                padding: 15px;
                border-radius: 8px;
                font-size: 16px;
                font-weight: bold;
                text-align: center;
                width: 400px;
                margin: 0 auto;
            ">
                Total Sites: ${total_sites}
            </div>
        `);

        // === Total Commits Card (orange) ===
        const total_commits = (frm.doc.commit_history || []).length;
        frm.set_df_property('total_commits', 'options', `
            <div style="
                background-color: #fd7e14;
                color: white;
                padding: 15px;
                border-radius: 8px;
                font-size: 16px;
                font-weight: bold;
                text-align: center;
                width: 400px;
                margin: 10px auto 0 auto;
            ">
                Total Commits: ${total_commits}
            </div>
        `);
    }
});

frappe.ui.form.on('Orchestrator Settings', {
    refresh(frm) {
        mask_field(frm, 'telegram_bot_token');
        mask_field(frm, 'chat_id');
    }
});

function mask_field(frm, fieldname) {
    const field = frm.get_field(fieldname);
    if (!field || !field.$input) return;

    // Set input type to password (••••••)
    field.$input.attr('type', 'password');

    // Prevent accidental copy
    field.$input.attr('autocomplete', 'new-password');
}
